mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM , B.* FROM ( SELECT U.USED_NO usedNo , U.USED_TITLE usedTitle , U.USED_PRICE usedPrice , U.STATUS status , U.ENROLL_DATE enrollDate , U.VIEW_COUNT viewCount , C.MANUFACTURER manufacturer , C.MODEL model , C.CAR_YEAR carYear , C.DISTANCE distance , C.TRANSMISSION transmission , C.FUEL_TYPE fuelType , C.REGION region , C.CAR_COLOR carColor , C.PHONE phone , CAT.CATEGORY_NAME categoryName , ATT.FILE_PATH thumbnail FROM CT_USED_LISTING U JOIN CT_CAR_INFO C ON U.USED_NO = C.USED_NO JOIN CT_USED_CATEGORY CAT ON U.CATEGORY = CAT.CATEGORY_NO LEFT JOIN ( SELECT REF_BNO , FILE_PATH FROM CT_USED_ATTACHMENT WHERE STATUS = 'Y' AND ROWNUM = 1 ) ATT ON ATT.REF_BNO = U.USED_NO
WHERE U.USED_TITLE LIKE '%' || #{keyword} || '%'
ORDER BY U.USED_NO DESC ) B ) WHERE RNUM BETWEEN #{startRow} AND #{endRow}

mapper.insert:
INSERT
  INTO
       CT_USED_LISTING
VALUES
	   (
	   #{usedNo}
     , #{userNo}
     , #{usedTitle}
     , #{usedContent}
     , #{usedPrice}
     , #{category}
     , '판매중'
     , SYSDATE
     , DEFAULT
     , #{thumbnail}
       )

INSERT
  INTO
       CT_USED_ATTACHMENT
VALUES
       (
       SEQ_USED_FILE_NO.NEXTVAL
     , #{refBno}
     , #{originName}
     , #{changeName}
     , #{filePath}
     , SYSDATE
     , 'Y'
       )

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT U.USED_NO usedNo , U.USER_NO userNo , U.USED_TITLE usedTitle , U.USED_PRICE usedPrice , U.STATUS status , U.ENROLL_DATE enrollDate , U.VIEW_COUNT viewCount , CAT.CATEGORY_NAME categoryName , CAR.MANUFACTURER manufacturer , CAR.MODEL model , CAR.CAR_YEAR carYear , CAR.DISTANCE distance , CAR.TRANSMISSION transmission , CAR.FUEL_TYPE fuelType , U.THUMBNAIL thumbnail FROM CT_USED_LISTING U JOIN CT_USED_CATEGORY CAT ON U.CATEGORY = CAT.CATEGORY_NO JOIN CT_CAR_INFO CAR ON U.USED_NO = CAR.USED_NO WHERE U.USER_NO = #{userNo}
AND U.STATUS = #{status}
ORDER BY U.USED_NO DESC ) A WHERE ROWNUM <= #{endRow} ) WHERE RNUM >= #{startRow}

mapper.update:
	UPDATE
		   CT_USED_LISTING
       SET
           USED_TITLE = #{usedTitle}
         , USED_CONTENT = #{usedContent}
         , USED_PRICE = #{usedPrice}
         , STATUS = #{status}
         , ENROLL_DATE = SYSDATE
     WHERE
           USED_NO = #{usedNo}
